    "ov.autModel": "Change its own model",
    "ov.autModelHint":
      "The agent can list the models this deployment can reach and switch itself to one (takes effect after it restarts). A model whose provider is not connected is refused. On a managed deployment a bigger model spends credits faster — the agent is told to say so.",
    "ov.autPrompt": "Edit its own instructions",
    "ov.autPromptHint":
      "The agent can rewrite its own system prompt when asked (full replacement, applies after restart). Every change is recorded in Config → Revisions under the agent's name, so you can review and roll it back.",
    "ov.autRestart": "Restart itself",
    "ov.autRestartHint":
      "The agent can restart itself so saved changes (model, prompt, channels, MCPs) take effect — a few seconds of downtime, scheduled just after its reply so the answer isn't cut off.",
    "ov.autSubagents": "Add subagents",
    "ov.autSubagentsHint":
      "The agent can add specialist subagents to itself — written from scratch or drafted from an archetype — and delegate work to them. New subagents apply after restart.",
    "ov.autMcps": "Connect services (MCP servers and built-in toolkits)",
    "ov.autMcpsHint":
      "The agent can search the MCP directory and add, remove or OAuth-authorize MCP servers on itself (Notion, CRMs, …). Sign-ins happen in the user's own browser; API keys go through the vault, never pasted into config. A new server connects after restart or when its OAuth completes.",
    "ov.autPlatforms": "Connect messaging platforms",
    "ov.autPlatformsHint":
      "The agent can wire messaging channels onto itself: token platforms (Telegram, Discord, Slack — it asks the user for the bot token, which is stored in the vault) and WhatsApp by QR (the code is shown right in the chat to scan). Connecting a channel opens a new inbound door — the agent is told to insist on an allowed-users list.",
    "ov.autSkills": "Manage its own skills",
    "ov.autSkillsHint":
      "The agent can list the skills it has and switch individual ones on or off for itself — the same switches on its Skills tab. It never installs, edits or deletes a skill, and switching off a common skill affects only this agent; every other agent keeps it. A change applies after restart.",
    "ov.autMagicLinks": "Send magic links",
    "ov.autMagicLinksHint":
      "The agent can send magic links: short-lived, PIN-protected pages a person opens in their own browser to finish something the chat cannot — sign in to a service or MCP server (OAuth or device flow), type an API key straight into the vault so it never passes through the conversation, connect WhatsApp/WeChat by QR or Telegram/Discord/Slack by bot token, edit the agent's instructions or one file, or open the dashboard on their phone. Links are the default way an agent connects itself to anything. Off removes the whole family (all magic_link_* tools) from this agent; a single tool can also be dropped on the Tools tab. Only owners can ask for a link (on a messenger, the channel's allowed-users list), group chats are refused, and every link raises an approval card on the stricter security profiles. Config → Magic links stays the hard off switch for the whole deployment and separately gates the dashboard sign-in link. Applies to the agent's next call.",
    "ov.autonomyNote":
      "These rows decide what the agent is capable of, not who may ask. Anything that writes — model, instructions, subagents, MCP services, channels, restart, sending a magic link — is additionally limited to people who own this agent: whoever created it, anyone granted Owner under Admin → Access, and deployment admins. On a messaging channel the sender must be on that channel's allowed-users list instead, which is what keeps WhatsApp pairing workable from a phone. Everyone else who can chat with the agent still gets the read-only half (list models, browse services and templates) and a refusal naming the remedy for the rest. Another agent, and any scheduled or background run, is always refused. The stricter security profiles then put a human approval card in front of every self-change; the developer profile applies them without asking. Deployment-wide defaults: Config → Agent self-configuration (admin only).",
    "ov.oversight": "Oversight",
    "ov.mode": "Mode",
    "ov.modeHint":
      "The baseline set of actions this agent must ask a human to approve. When a gated tool runs, the turn pauses and the request appears in Approvals (and in chat) until you allow or deny it — unanswered requests are denied after 5 minutes. The toggles below only ever add more approvals on top of the mode; a per-tool override in Approval overrides beats both.",
    "ov.profileTrusted": "Trusted — act freely",
    "ov.profileSupervised": "Supervised — ask before writes",
    "ov.profileLocked": "Locked-down — strictest",
    "ov.modeOpt.trusted":
      "Asks only before moving money (wallet_send) and before storing a credential (secret_set). Everything else — sending email, posting, editing files, running shell commands — happens without asking. Best for a personal agent on your own machine.",
    "ov.modeOpt.supervised":
      "Everything Trusted asks about, plus: writes to outside services (email, calendar, Slack, GitHub, Notion, Drive, social posts, Stripe, and agent self-management), every shell command, and reading a stored credential (secret_get). It can still read files and edit its own workspace freely. Best for an agent that talks to real customers or real accounts.",
    "ov.modeOpt.locked":
      "Everything Supervised asks about, plus writing or editing any file on disk and handing work to a subagent. In practice the agent reads and reasons freely but nearly every action that changes something waits for you. It also rejects — rather than redacts — messages containing personal info, and audits skills strictly enough that a merely suspicious one is quarantined instead of loaded. Expect frequent approval prompts; this is for high-stakes deployments where a wrong move is expensive.",
    "ov.askWrite": "Ask before write actions",
    "ov.askWriteHint":
      "Adds approval for writes to outside services — sending email, creating calendar events, posting to Slack/X/LinkedIn, opening GitHub PRs and issues, uploading to Drive, creating Stripe invoices, and any change an admin agent makes to your Olano setup. Already included in Supervised and Locked-down, so this only changes anything in Trusted mode.",
    "ov.askShell": "Ask before shell commands",
    "ov.askShellHint":
      "Adds approval for anything that executes code on the machine — the shell/execute tools and self-update. Every command shows you its exact text before it runs. Already included in Supervised and Locked-down. Has no effect if the agent's Access is not \"Read, Write & Execute\", since it then has no shell at all.",
    "ov.approvalOverrides": "Approval overrides (advanced)",
    "ov.approvalOverridesHint":
      "Pin one specific tool on or off, whatever the mode and toggles say — for example require approval for gmail_send only, or exempt one tool you use constantly. This is the highest-precedence rule. Note: while a chat session is in Auto mode, that session approves everything regardless of what is set here.",
    "ov.approvalNoTools": "No agent-level tools selected yet.",
