    "skills.gated": "Needs admin tools",
    "skills.gatedHint":
      "This skill is written for agents that hold specific tools ({tools}) and this agent does not have them, so it is not described in the agent’s prompt, cannot be delegated to, and has no switch — the switch only edits the agent’s denylist, which is not what keeps this skill out. To give the agent the skill, grant the tools first (this agent’s Tools tab, or `tools` in its agent.json5); it then appears on its own. Skills that declare no required tools are never gated.",
    // The switch's full explanation — what it changes, what it does NOT touch,
    // and when it takes effect. Common skills are shared by every agent on the
    // box, so "does this delete it for everyone?" is the first question a switch
    // like this raises, and it gets answered before it is asked.
    "skills.toggleHint":
      "Use the switch on each row to choose which skills this agent loads. A skill that is off is not described in the agent’s prompt, cannot be delegated to, and is ignored by self-learning — but it stays on disk and stays listed here, so you can switch it back on at any time. Turning off a common skill only affects this agent; other agents keep it. “Turn all on” / “Turn all off” apply to every skill listed below, or just the search results while a search is active. All skills are on by default. A row marked “Needs admin tools” has no switch: that skill declares tools this agent does not have, and granting them (Tools tab) is what makes it appear. Changes save on their own and apply the next time the agent restarts.",
