    "catalog.group.tools": "Tools",
    "catalog.tools.intro": "What this connector lets the agent do beyond replying in a conversation. The switches are saved with the connector and a running agent picks them up within seconds; the same switches are on the agent's Tools tab.",
    "catalog.tools.everyday": "Everyday tools",
    "catalog.tools.everydayHelp": "On for every agent that has this connector. Only the agent's owner or an administrator can have it use them; a customer writing in cannot. Switch one off to take it away from this agent.",
    "catalog.tools.admin": "Account administration",
    "catalog.tools.adminHelp": "Off until an administrator switches them on, for the one agent that manages the Twilio account: what they change or read belongs to the whole account and every agent on it. No agent can switch them on by itself. Under the Supervised and Locked-down security profiles, a change waits for your approval.",
    "catalog.tools.loading": "Loading the agent's current switches...",
    "catalog.whatsappTwilio.tool.whatsapp_template_list": "List the templates WhatsApp approved for the account, with their placeholders and buttons.",
    "catalog.whatsappTwilio.tool.whatsapp_template_send": "Send an approved template to a number: the only message WhatsApp delivers to someone who has not written in 24 hours. Waits for WhatsApp's verdict and reports it.",
