    "catalog.whatsappMetaApi.tool.whatsapp_template_list": "List the templates WhatsApp approved for the WhatsApp Business Account, with their placeholders, buttons and the category WhatsApp bills each as.",
    "catalog.whatsappMetaApi.tool.whatsapp_template_send": "Send an approved template to a number: the only message WhatsApp delivers to someone who has not written in 24 hours. Waits for WhatsApp's verdict and reports it, with the billing category.",
    "catalog.whatsappMetaApi.tool.whatsapp_message_status": "Check later whether a message was delivered or read, or why it failed, and how WhatsApp billed it.",
