    "mcp.directory.everything-stdio.description": "参考 MCP 服务器，提供工具、提示词和资源。",
    "mcp.directory.time-python-stdio.description": "用于获取当前时间和时区转换的小型 Python MCP 服务器。",
    "mcp.directory.everything-sse.description": "同一参考服务器，通过旧版 SSE 传输方式提供。",
    "mcp.directory.everything-http.description": "参考服务器，通过流式 HTTP 提供。",
    "mcp.directory.stripe-example.description": "远程 Stripe MCP 服务器 — 需要 OAuth。先测试，再点击授权。",
    "mcp.directory.github-docker-stdio.description": "官方 GitHub MCP 服务器，在本地 Docker 中运行 — 需要个人访问令牌。",
    "mcp.preset.hubspot.notes": "在 HubSpot 中创建一个 MCP 授权应用，以获取客户端 ID 和客户端密钥。",
    "mcp.preset.stripe.notes": "在浏览器中完成授权 — 无需创建应用。",
    "mcp.preset.notion.notes": "一键浏览器授权即可访问你的 Notion 工作区。",
    "mcp.preset.linear.notes": "在浏览器中完成授权 — 无需管理 API 密钥。",
    "mcp.preset.sentry.notes": "连接时会启动 OAuth 流程 — 无需设置 API 密钥。",
    "mcp.preset.github.notes": "在浏览器中通过 OAuth 完成一次性身份验证。",
    "mcp.preset.intercom.notes":
      "适用于美国托管工作区的浏览器 OAuth。欧盟托管的工作区请将 URL 改为 https://mcp.eu.intercom.com/mcp。暂不支持澳大利亚托管的工作区。",
    "mcp.preset.paypal.notes": "在浏览器中授权，支持跨设备单点登录。",
    "mcp.preset.square.notes": "在浏览器中完成 OAuth 2.1 授权。",
    "mcp.preset.canva.notes":
      "Canva 需要你自己的应用：在 Canva 开发者门户中创建一个应用，开启 Canva MCP，添加 Olano 显示的重定向 URL，然后填入它的客户端 ID 和客户端密钥。每个人都使用自己的 Canva 账户登录。",
    "mcp.preset.webflow.notes": "浏览器 OAuth 授权后即可访问你的 Webflow 站点。",
    "mcp.preset.wix.notes": "在浏览器中完成授权 — 无需创建应用。",
    "mcp.preset.asana.notes":
      "Asana 的 V2 服务器不支持自动注册客户端：请在 Asana 开发者控制台中创建一个 MCP 应用，添加 Olano 显示的重定向 URL，在“Manage distribution”中允许你的工作区，然后填入它的客户端 ID 和客户端密钥。",
    "mcp.preset.atlassian.notes":
      "浏览器 OAuth 会遵循你现有的 Jira 和 Confluence 权限（仅限 Atlassian Cloud）。如果授权被拒绝，可能需要组织管理员在 Atlassian Administration → Rovo MCP server 中将你的 Olano 地址添加为受信任的域。",
    "mcp.preset.vercel.notes": "每次连接都会在浏览器中显示同意界面的 OAuth（只读）。",
    "mcp.preset.zapier.notes": "在浏览器中使用你的 Zapier 账户登录；Zapier 会在登录过程中为你设置 MCP 服务器，因此无需事先创建任何内容。",
    "mcp.preset.parallel.notes":
      "免费托管的网页搜索（web_search + web_fetch 工具）。个人使用无需密钥；如需更高限额，可将 Parallel API 密钥作为 Bearer 请求头传递。",
    "mcpmodal.formSubtitle": "配置传输方式、stdio 启动详情、环境变量和高级 JSON。",
    "mcpmodal.guidedTab": "引导模式",
