    "skills.turnOnAria": "Activar la habilidad {name} para este agente",
    "skills.gated": "Necesita herramientas de administración",
    "skills.gatedHint":
      "Esta habilidad está escrita para agentes que tienen herramientas concretas ({tools}) y este agente no las tiene, así que no se describe en su prompt, no se le puede delegar y no tiene interruptor: el interruptor solo edita la lista de exclusión del agente, que no es lo que mantiene fuera esta habilidad. Para dársela al agente, concede primero las herramientas (pestaña Herramientas de este agente, o `tools` en su agent.json5); después aparece sola. Las habilidades que no declaran herramientas requeridas nunca se restringen.",
    "skills.toggleHint":
      "Usa el interruptor de cada fila para elegir qué habilidades carga este agente. Una habilidad desactivada no se describe en el prompt del agente, no se le puede delegar y el autoaprendizaje la ignora, pero sigue en el disco y se sigue listando aquí, así que puedes volver a activarla cuando quieras. Desactivar una habilidad común solo afecta a este agente; los demás la conservan. “Activar todas” / “Desactivar todas” actúan sobre las habilidades listadas abajo, o solo sobre los resultados mientras haya una búsqueda activa. Todas las habilidades están activas por defecto. Los cambios se guardan solos y se aplican en el próximo reinicio del agente.",
    // ── Skill viewer ───────────────────────────────────────────────
