    "adv.title": "Todos los ajustes",
    "adv.subtitle":
      "Cada campo de agent.json5, generado a partir del esquema de configuración — así nada queda encerrado tras el archivo en bruto. Los campos estructurados (herramientas, conectores, memoria…) se editan en sus propias pestañas; el resto está aquí.",
