    // ── Connector catalog: the connector's tools ────────────────────
    "catalog.group.tools": "Herramientas",
    "catalog.tools.intro": "Lo que este conector permite hacer al agente además de responder en una conversación. Los interruptores se guardan con el conector y un agente en marcha los aplica en segundos; los mismos interruptores están en la pestaña Herramientas del agente.",
    "catalog.tools.everyday": "Herramientas de uso diario",
    "catalog.tools.everydayHelp": "Activas para todo agente que tenga este conector. Solo el propietario del agente o un administrador puede hacer que las use; un cliente que escribe no puede. Desactiva una para quitársela a este agente.",
    "catalog.tools.admin": "Administración de la cuenta",
    "catalog.tools.adminHelp": "Desactivadas hasta que un administrador las active, para el único agente que gestiona la cuenta de Twilio: lo que cambian o leen pertenece a toda la cuenta y a todos sus agentes. Ningún agente puede activarlas por sí mismo. Con los perfiles de seguridad Supervisado y Bloqueado, un cambio espera tu aprobación.",
    "catalog.tools.loading": "Cargando los interruptores actuales del agente...",
    "catalog.whatsappTwilio.tool.whatsapp_template_list": "Lista las plantillas que WhatsApp aprobó para la cuenta, con sus marcadores y botones.",
    "catalog.whatsappTwilio.tool.whatsapp_template_send": "Envía una plantilla aprobada a un número: el único mensaje que WhatsApp entrega a quien no ha escrito en 24 horas. Espera el veredicto de WhatsApp y lo informa.",
    "catalog.whatsappTwilio.tool.whatsapp_message_status": "Consulta más tarde si un mensaje se entregó o se leyó, o por qué falló.",
    "catalog.whatsappTwilio.tool.whatsapp_window_status": "Consulta si la ventana de 24 horas está abierta para un número, es decir, si se entregaría un mensaje normal o solo una plantilla.",
    "catalog.whatsappTwilio.tool.whatsapp_template_create": "Crea una plantilla (texto, marcadores, botones de respuesta o de web/teléfono) y la envía a WhatsApp para su aprobación.",
    "catalog.whatsappTwilio.tool.whatsapp_template_submit": "Envía a aprobación una plantilla creada pero nunca enviada.",
    "catalog.whatsappTwilio.tool.whatsapp_template_status": "El estado de aprobación de una o de todas las plantillas, con el motivo de WhatsApp cuando rechazó una.",
    "catalog.whatsappTwilio.tool.whatsapp_template_delete": "Elimina una plantilla de la cuenta. Exige escribir el nombre de nuevo; no se puede deshacer.",
    "catalog.whatsappTwilio.tool.whatsapp_sender_status": "Los números de WhatsApp de la cuenta: en línea o no, la calificación de calidad de Meta, el límite de mensajes, el perfil de empresa.",
    "catalog.whatsappTwilio.tool.whatsapp_profile_update": "Cambia el perfil de empresa que ven los clientes: línea de presentación, descripción, dirección, correo, web, categoría.",
    "catalog.whatsappTwilio.tool.twilio_account_balance": "El saldo actual de la cuenta de Twilio.",
    "catalog.whatsappTwilio.tool.twilio_usage_summary": "El gasto en WhatsApp de este mes, el mes pasado, hoy o ayer, por categoría, con el total de la cuenta.",
    "catalog.whatsappMetaApi.tool.whatsapp_template_list": "Lista las plantillas que WhatsApp aprobó para la WhatsApp Business Account, con sus marcadores, botones y la categoría con la que WhatsApp factura cada una.",
    "catalog.whatsappMetaApi.tool.whatsapp_template_send": "Envía una plantilla aprobada a un número: el único mensaje que WhatsApp entrega a quien no ha escrito en 24 horas. Espera el veredicto de WhatsApp y lo informa, con la categoría de facturación.",
    "catalog.whatsappMetaApi.tool.whatsapp_message_status": "Comprueba más tarde si un mensaje se entregó o se leyó, o por qué falló, y cómo lo facturó WhatsApp.",
    "catalog.whatsappMetaApi.tool.whatsapp_window_status": "Comprueba si la ventana de 24 horas está abierta para un número, es decir, si llegaría un mensaje normal o solo una plantilla.",
    "catalog.whatsappMetaApi.tool.whatsapp_template_create": "Crea una plantilla (texto, marcadores, botones de respuesta o de web/teléfono). Meta la revisa en cuanto se crea.",
    "catalog.whatsappMetaApi.tool.whatsapp_template_submit": "Indica en qué estado está una plantilla: en la Cloud API de Meta cada plantilla se envía a revisión al crearse, así que no hay un envío aparte.",
    "catalog.whatsappMetaApi.tool.whatsapp_template_status": "El estado de aprobación y la categoría de una o de todas las plantillas, con el motivo de WhatsApp si rechazó alguna y una nota si la pasó a otra categoría.",
    "catalog.whatsappMetaApi.tool.whatsapp_template_delete": "Elimina una plantilla (un idioma) de la WhatsApp Business Account. Pide escribir el nombre de nuevo; no se puede deshacer.",
    "catalog.whatsappMetaApi.tool.whatsapp_sender_status": "Los números de la Business Account: estado, nombre visible, la calificación de calidad de Meta, el límite de mensajes, el perfil de empresa.",
    "catalog.whatsappMetaApi.tool.whatsapp_profile_update": "Cambia el perfil de empresa que ven los clientes: línea de información, descripción, dirección, correo, web, categoría.",
